def solution(grid_str):
    """
    Final solution for Arthur's Apartment problem.
    """
    lines = grid_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:]]

    def is_free(r, c):
        return 0 <= r < n and 0 <= c < m and grid[r][c] == '.'

    def get_component(start_r, start_c):
        comp = []
        if not is_free(start_r, start_c):
            return comp
        visited = set()
        q = [(start_r, start_c)]
        visited.add((start_r, start_c))
        while q:
            r, c = q.popleft()
            comp.append((r, c))
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if is_free(nr, nc) and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return comp

    def is_valid(component):
        if not component:
            return True
        min_r, max_r = min(c[0] for c in component), max(c[0] for c in component)
        min_c, max_c = min(c[1] for c in component), max(c[1] for c in component)
        return (max_r - min_r + 1) * (max_c - min_c + 1) == len(component)

    # Check if currently valid
    visited = [[False]*m for _ in range(n)]
    all_valid = True
    for r in range(n):
        for c in range(m):
            if grid[r][c] == '.' and not visited[r][c]:
                comp = get_component(r, c)
                if not is_valid(comp):
                    all_valid = False
                    break
        if not all_valid: break

    if all_valid:
        return grid_str

    # Try removing walls greedily
    for _ in range(n * m):
        visited = [[False]*m for _ in range(n)]
        all_valid = True
        for r in range(n):
            for c in range(m):
                if grid[r][c] == '.' and not visited[r][c]:
                    comp = get_component(r, c)
                    if not is_valid(comp):
                        all_valid = False
                        break
                visited[r][c] = True
            if not all_valid: break

        if all_valid:
            break

        best_wall = None
        for r in range(n):
            for c in range(m):
                if grid[r][c] == '*':
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if is_free(nr, nc):
                            grid[r][c] = '.'
                            visited = [[False]*m for _ in range(n)]
                            all_ok = True
                            for pr in range(n):
                                for pc in range(m):
                                    if grid[pr][pc] == '.' and not visited[pr][pc]:
                                        cp = get_component(pr, pc)
                                        if not is_valid(cp):
                                            all_ok = False
                                            break
                                        visited[pr][pc] = True
                                if not all_ok: break
                            if all_ok:
                                best_wall = (r, c)
                                break
                            grid[r][c] = '*'
                    if best_wall: break

        if not best_wall:
            break

    return "\n".join("".join(row) for row in grid)
