        if not visited[i]:
            count = 0
            queue = [i]
            visited[i] = True
            while queue:
                node = queue.pop(0)
                count += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            size_list.append(count)

    # Check if any existing component is already lucky
    lucky_numbers = generate_lucky_numbers(n)
    if any(size in lucky_numbers for size in size_list):
        return "0\n"

    # Count occurrences of each component size
    size_counts = Counter(size_list)

    # DP: dp[s] = minimum components needed to achieve sum s
    dp = {0: 0}

    # Handle size 1 specially (unbounded since we can use all of them)
    ones_count = size_counts.get(1, 0)
    if ones_count > 0:
        max_ones = min(ones_count, n)
        for s in range(1, max_ones + 1):
            dp[s] = dp.get(s, float('inf'))
            if s - 1 in dp:
                dp[s] = min(dp[s], dp[s - 1] + 1)

    # Handle other sizes using 0-1 knapsack (each can be used at most once)
    for size, count in size_counts.items():
        if size == 1:
            continue

        # For each copy of this size
        for _ in range(count):
            new_dp = dp.copy()
            for s in sorted(dp.keys(), reverse=True):
                if s + size <= n and (s + size) in range(1, n + 1):
                    if s in dp:
                        new_val = dp[s] + 1
                        if new_val < new_dp.get(s + size, float('inf')):
                            new_dp[s + size] = new_val
            dp = new_dp

    # Find minimum roads needed (components - 1)
    min_roads = float('inf')
    for L in lucky_numbers:
        if L in dp:
            roads = dp[L] - 1
            if roads >= 0:
                min_roads = min(min_roads, roads)

    if min_roads == float('inf'):
        return "-1\n"

    return f"{min_roads}\n"


