def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    if n % 2 != 0:
        return '-1\n'

    # Parse costs: costs[i][j] = cost for city i (0-indexed) to build rail to city j
    costs = [[0] * n for _ in range(n)]
    for i in range(n):
        row = list(map(int, lines[i + 1].split()))
        # Row has n-1 values: skip self (position i)
        for j in range(n - 1):
            if j + 1 < i or j + 1 > i:
                # j+1 is city index, need to place correctly
                col = j if j < i else j + 1
                costs[i][col] = row[j]

    # Create preference lists: lower cost = higher preference
    preferences = []
    for i in range(n):
        pref = []
        for j in range(n):
            if i != j:
                pref.append((costs[i][j], j))  # (cost for i with j, city j)
        pref.sort(key=lambda x: x[0])  # Lower cost first (better preference)
        preferences.append([p[1] for p in pref])  # Just city indices in preference order

    # Backtracking to find valid matching
    partner = [-1] * n  # partner[i] = partner of city i
    match = [[False] * n] * n  # match[i][j] = True if i and j are paired

    def check_stability():
        """Check if current matching is stable"""
        # Get reverse mapping: who is partner of each city
        current_partners = [partner[i] for i in range(n)]

        # Check all pairs of cities that are NOT together
        for i in range(n):
            my_partner = current_partners[i]
            for j in range(i + 1, n):
                if my_partner != -1 and my_partner != j:
                    # i is with someone else, j is with someone else
                    # Would both prefer each other?
                    cost_i_j = costs[i][j]
                    cost_j_i = costs[j][i]
                    cost_i_current = costs[i][my_partner]
                    cost_j_current = costs[j][partner[j]]

                    if cost_i_j < cost_i_current and cost_j_i < cost_j_current:
                        return False

        return True

    def backtrack():
        # Find first unpaired city
        for i in range(n):
            if partner[i] == -1:
                # Try pairing i with each available city j
                for j in range(i + 1, n):
                    if partner[j] == -1:
                        partner[i] = j
                        partner[j] = i

                        if check_stability():
                            return True

                        partner[i] = -1
                        partner[j] = -1

                return False
        return True

    if backtrack():
        result = []
        for i in range(n):
            result.append(str(partner[i] + 1))  # Convert to 1-indexed, each on new line
        return '\n'.join(result) + '\n'
    else:
        return '-1\n'


