def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 3:
        return '0'
    s1 = lines[0].strip()
    s2 = lines[1].strip()
    virus = lines[2].strip()

    n, m, l = len(s1), len(s2), len(virus)

    if l == 0:
        # Empty virus - use standard LCS
        dp = [[0] * (m + 1) for _ in range(n + 1)]
        for i in range(n):
            for j in range(m):
                if s1[i] == s2[j]:
                    dp[i + 1][j + 1] = dp[i][j] + 1
                else:
                    dp[i + 1][j + 1] = max(dp[i][j + 1], dp[i + 1][j])

        if dp[n][m] == 0:
            return '0'

        # Reconstruct LCS
        result = []
        i, j = n, m
        while i > 0 and j > 0:
            if i > 0 and j > 0 and s1[i - 1] == s2[j - 1]:
                result.append(s1[i - 1])
                i -= 1
                j -= 1
            elif i > 0 and dp[i][j] == dp[i - 1][j]:
                i -= 1
            elif j > 0 and dp[i][j] == dp[i][j - 1]:
                j -= 1
            else:
                break

        if len(result) == 0:
            return '0'
        return ''.join(reversed(result))

    # Build KMP failure function for virus pattern
    pi = [0] * l
    j = 0
    for i in range(1, l):
        while j > 0 and virus[i] != virus[j]:
            j = pi[j - 1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    # Precompute transition table: for state k and char c, what's the new state?
    trans = [[0] * 26 for _ in range(l)]
    for k in range(l):
        for c in range(26):
            char_c = chr(ord('A') + c)
            temp = k
            while temp > 0 and char_c != virus[temp]:
                temp = pi[temp - 1]
            if char_c == virus[temp]:
                temp += 1
            trans[k][c] = temp

    # DP: dp[i][j][k] = longest common subsequence using s1[:i], s2[:j], virus state k
    dp = [[[0] * l for _ in range(n + 1)] for _ in range(m + 1)]
    parent = [[[None] * l for _ in range(n + 1)] for _ in range(m + 1)]

    for i in range(n):
        for j in range(m):
            for k in range(l):
                # Try matching s1[i] and s2[j]
                if s1[i] == s2[j]:
                    nc = ord(s1[i]) - ord('A')
                    nk = trans[k][nc]
                    if nk < l:  # Don't complete virus
                        if dp[i][j][k] + 1 > dp[i + 1][j + 1][nk]:
                            dp[i + 1][j + 1][nk] = dp[i][j][k] + 1
                            parent[i + 1][j + 1][nk] = ('match', (i, j, k))

                # Skip s1[i]
                if dp[i][j][k] > dp[i + 1][j][k]:
                    dp[i + 1][j][k] = dp[i][j][k]
                    parent[i + 1][j][k] = ('skip1', (i, j, k))

                # Skip s2[j]
                if dp[i][j][k] > dp[i][j + 1][k]:
                    dp[i][j + 1][k] = dp[i][j][k]
                    parent[i][j + 1][k] = ('skip2', (i, j, k))

    # Find best final state
    best_len = 0
    for k in range(l):
        if dp[n][m][k] > best_len:
            best_len = dp[n][m][k]

    if best_len == 0:
        return '0'

    # Reconstruct the solution
    result = []
    i, j, k = n, m, k
    # Find which k had the best length
    while i > 0 and j > 0 and j > 0:
        p = parent[i][j][k]
        if p is None:
            break
        action, (prev_i, prev_j, prev_k) = p

        if action == 'match':
            result.append(s1[prev_i])
            i, j, k = prev_i + 1, prev_j + 1, prev_k
        else:
            i, j = prev_i + 1, prev_j + 1

        # Find best k at this position
        for ck in range(l):
            if dp[i][j][ck] == best_len - len(result):
                k = ck
                break

    if len(result) == 0:
        return '0'
    return ''.join(reversed(result))
