def solution(input_str):
    import sys
    sys.setrecursionlimit(200000)

    parts = list(map(int, input_str.strip().split()))
    n, p, l, r = parts

    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        g, y, x = extended_gcd(b % a, a)
        y -= (b // a) * x
        return g, x, y

    def mod_inverse(a, m):
        g, x, _ = extended_gcd(a % m, m)
        if g != 1:
            return None
        return x % m

    def nCr(n_val, r_val):
        if r_val < 0 or r_val > n_val:
            return 0
        num = 1
        den = 1
        for i in range(r_val):
            num = (num * (n_val - i)) % p
            den = (den * (i + 1)) % p
        inv_den = mod_inverse(den, p)
        if inv_den is None:
            return 0
        return (num * inv_den) % p

    inv_a1 = [0] * (n + 2)
    for i in range(1, n + 2):
        inv_a1[i] = mod_inverse(i, p)

    total = 0
    for k in range(l, r + 1):
        for a in range(k, min(n, (n + k) // 2 + 1)):
            if a + (a - k) > n:
                continue
            b = a - k
            n_ab = a + b
            term = nCr(n, n_ab)
            term = (term * nCr(n_ab, a)) % p
            term = (term * (k + 1)) % p
            inv = inv_a1[a + 1]
            if inv is None:
                continue
            term = (term * inv) % p
            total = (total + term) % p

    return str(total)
