def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    edges = []
    for i in range(1, m + 1):
        a, b = map(int, lines[i].split())
        edges.append((a, b))

    # Build conflict graph: edges cross if their endpoints interleave
    conflict = [[] for _ in range(m)]

    for i in range(m):
        for j in range(i + 1, m):
            a1, b1 = edges[i]
            a2, b2 = edges[j]

            # Share an endpoint - no crossing conflict
            if a1 == a2 or a1 == b2 or b1 == a2 or b1 == b2:
                continue

            # Normalize edges (smaller endpoint first)
            if a1 > b1:
                a1, b1 = b1, a1
            if a2 > b2:
                a2, b2 = b2, a2

            # Check if edges cross: (a1, b1) and (a2, b2) cross if they interleave
            # That is: a1 < a2 < b1 < b2 or a2 < a1 < b2 < b1
            if (a1 < a2 < b1 < b2) or (a2 < a1 < b2 < b1):
                conflict[i].append(j)
                conflict[j].append(i)

    # Check if conflict graph is bipartite using BFS/DFS coloring
    color = [-1] * m
    possible = True
    ans = []

    for start in range(m):
        if color[start] == -1:
            color[start] = 0
            queue = [start]
            while queue:
                u = queue.pop(0)
                for v in conflict[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        queue.append(v)
                    elif color[v] == color[u]:
                        possible = False
                        break
                if not possible:
                    break
            if not possible:
                break

    if not possible:
        return "Impossible"
    else:
        for c in color:
            ans.append('i' if c == 0 else 'o')
        return ''.join(ans)
