        s2 = "A" * m
        if verify(k, s1, s2) == x:
            return s1 + "\n" + s2 + "\n"
        s1 = "Z" * n
        s2 = "Z" * m
        if verify(k, s1, s2) == x:
            return s1 + "\n" + s2 + "\n"
        return "Happy new year!\n"

