        return "Happy new year!\n"

    # For k >= 4 with small n, m
    if k == 4 and n <= 3 and m <= 3:
        if find_s4(k, x, n, m):
            return found_result['s1'] + "\n" + found_result['s2'] + "\n"
        return "Happy new year!\n"

    return "Happy new year!\n"


