def find_s3(k, x, n, m):
    """Find s1, s2 for k=3"""
    global found_result
    found_result = None

    for i in range(1 << n):
        s1 = ""
        for j in range(n):
            if (i >> j) & 1:
                s1 += "A"
            else:
                s1 += "Z"

        for j in range(1 << m):
            s2 = ""
            for l in range(m):
                if (j >> l) & 1:
                    s2 += "A"
                else:
                    s2 += "Z"

            if verify(3, s1, s2) == x:
                found_result = {'s1': s1, 's2': s2}
                return True
    return False


def find_s4(k, x, n, m):
