def solution(s):
    lines = s.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    arr = list(map(int, lines[1].split()))

    if n == 1:
        return str(0)

    def get_divisors(x):
        divs = set()
        for d in range(1, int(x**0.5) + 1):
            if x % d == 0:
                divs.add(d)
                divs.add(x // d)
        return divs

    candidates = set()
    for i in [0, 1] + list(range(n - 1, max(0, n - 11), -1)):
        for x in [arr[i] - 1, arr[i], arr[i] + 1]:
            candidates.update(get_divisors(x))

    divides = set(d for d in candidates if d > 1)

    def calc_change_cost(arr, g):
        cost = 0
        for x in arr:
            rem = x % g
            if rem == 0:
                continue
            elif rem <= 1 or rem >= g - 1:
                cost += b
            else:
                return float('inf')
        return cost

    ans = float('inf')

    for g in divides:
        ans = min(ans, calc_change_cost(arr, g))
        for i in range(1, n):
            cost = i * a + calc_change_cost(arr[i:], g)
            ans = min(ans, cost)
        for i in range(1, n):
            cost = i * a + calc_change_cost(arr[:n-i], g)
            ans = min(ans, cost)

    return str(ans)
